package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)

	var S, T string
	counter := 0

	for scanner.Scan() {
		line := scanner.Text()
		if counter == 0 {
			S = line
		} else {
			T = line

			ans := "YES"
			j := 0
			for i := len(T) - 1; i >= 0; i-- {
				if T[i] != S[j] {
					ans = "NO"
					break
				}
				j++
			}

			fmt.Println(ans)
		}
		counter++
	}
}

